// Client Script for Doctype: Task
// Paste into Client Script (Type = Client) -> Doctype = Task

function applyTaskDepStyle() {
    // Your CSS as text 
    var task_dep_styles = `
        .modal-body div[data-fieldname="dependencies_rows"] {
            & .row-check.col {
                flex: 0 1 12px;
            }
            & .row .col-xs-1 {
                flex: 1 1 5%;
                max-width: 10%;
            }
        }
    `;

    var styleSheet = document.createElement("style");
    styleSheet.textContent = task_dep_styles;
    document.head.appendChild(styleSheet);
}

applyTaskDepStyle();

const LARGE_AMOUNT_THRESHOLD = 200;

frappe.ui.form.on('Task', {
    refresh: function(frm) {
        // Add buttons
        let group = __("Зависимости");
        if (!frm.is_new()) {
            frm.add_custom_button('<i class="fa fa-arrows-v" aria-hidden="true"></i> ' + __('Проверить все'), function() {
                _tds_preview(frm, "both");
            }, group);
            frm.add_custom_button('<i class="fa fa-level-down" aria-hidden="true"></i> ' + __('По дереву вниз'), function() {
                _tds_preview(frm, "downstream" );
            }, group);
            frm.add_custom_button('<i class="fa fa-level-up" aria-hidden="true"></i> ' + __('По дереву вверх'), function() {
                _tds_preview(frm, "upstream" );
            }, group);
        }
        // Run quick check to highlight conflicts
        _tds_quick_check(frm);
        
        frm.set_query("predecessor", "custom_relations", function(doc, cdt, cdn) {  
            return {  
                filters: [  
                        ["Task", "project", "=", frm.doc.project],  
                        ["Task", "name", "not in", [frm.docname]],  
                        ["Task", "name", "not descendants of", frm.docname],  
                        ["Task", "name", "not ancestors of", frm.docname]  
                    ]
            };  
        });  
    }
});

frappe.ui.form.on("Task Relation", {
    predecessor: function(frm, cdt, cdn) {
        // When row added, client-side basic check then server validate
        let row = locals[cdt][cdn];
        if (!row.predecessor) {
            return;
        }
        if (row.predecessor === frm.doc.name) {
            frappe.msgprint(__('Predecessor cannot be same as current task'));
            frappe.model.clear_doc(cdt, cdn);
            return;
        }
        validate_relation(frm, row, cdt, cdn);
    },
    type: function(frm, cdt, cdn) {
        let row = locals[cdt][cdn];
        validate_relation(frm, row, cdt, cdn);
    },
    custom_relations_add: function(frm, cdt, cdn) {
        let row = locals[cdt][cdn];
        row.project = frm.doc.project;
    },
    custom_relations_remove: function(frm, cdt, cdn) {
        // If a relation removed, propose recalc
        //frappe.show_alert({message: __('Relation removed — preview changes'), indicator: 'orange'});
        //_tds_preview(frm, "downstream");
    }
});

function validate_relation(frm , row, cdt, cdn, field="predecessor") {
    // call server validate
    frappe.call({
        method: "validate_relation",
        args: {
            parent_successor: frm.doc.name,
            predecessor: row.predecessor,
            rel_type: row.type,
            buffer_days: row.buffer_days || 0
        },
        callback: function(r) {
            if (!r || !r.message) return;
            let res = r.message;
            if (res.ok) {
                // ok — keep row
                frappe.show_alert({message: __('Relation validated'), indicator: 'green'});
            } else {
                frappe.model.set_value(cdt, cdn, field, "");  
                frappe.throw( res.error + (res.path ? ('<br>Path: ' + res.path.join(' -> ')) : '') );
            }
        }
    });
}

// Helper: quick check of direct relations and highlight fields
function _tds_quick_check(frm) {
    // call get_relations_for_task and mark warnings
    if (frm.is_new()) return;
    frappe.call({
        method: "get_relations_for_task",
        args: {task: frm.doc.name},
        callback: function(r) {
            //TODO Переделать на даты по календарю!
            if (!r || !r.message) return;
            let data = r.message;
            let has_conflict = false;
            // check predecessors
            (data.predecessors || []).forEach(function(pr) {
                // simple check: if FS and predecessor.exp_end + buffer > current start -> conflict
                if (!pr.exp_end_date) return;
                if (!frm.doc.exp_start_date) return;
                // convert strings to Date for simple compare (ignoring business days here)
                let pred_end = new Date(pr.exp_end_date);
                let cur_start = new Date(frm.doc.exp_start_date);
                // we only do a naive check client-side, server preview is authoritative
                if (pr.type === __("FS (Finish → Start)")) {
                    let buf = parseInt(pr.buffer_days || 0);
                    pred_end.setDate(pred_end.getDate() + buf);
                    if (pred_end > cur_start) {
                        has_conflict = true;
                    }
                }
            });
            // set indicator
            if (has_conflict) {
                frm.set_df_property('exp_start_date', 'read_only', false);
                // add message
                frm.dashboard.add_comment(__('Warning: some dependencies may be violated'), 'orange');
            }
        }
    });
}

// Main preview function
function _tds_preview(frm, direction) {
    frappe.call({
        method: "preview_propagation",
        args: {
            changed_task: frm.doc.name,
            direction: direction
        },
        callback: function(r) {
            if (!r || !r.message) return;
            let msg = r.message;
            _tds_show_preview_dialog(frm, msg.preview);
        }
    });
}

function _tds_show_preview_dialog(frm, preview_list) {
    if (!preview_list || preview_list.length === 0) {
        frappe.msgprint(__('Не выявлено необходимых изменений, вызванных нарушением зависимостей задач'));
        return;
    }

    // Create dialog
    let d = new frappe.ui.Dialog({
        title: __('Необходимые изменения для устранения нарушений зависимостей задач'),
        size: 'extra-large',
        fields: [
            {
                fieldname: 'dependencies_rows',
                fieldtype: 'Table',
                cannot_add_rows: 1,
                cannot_delete_rows: 1,
                in_place_edit: true,
                fields: [
                    { label: __('Задача'), fieldname: 'subject', fieldtype: 'Data', read_only: 1, in_list_view: 1, columns: 2 },
                    { label: __("Текущ. начало"), fieldname: 'current_start', fieldtype: 'Date', precision: 1, read_only: 1, in_list_view: 1, columns: 1 },
                    { label: __("Текущ. окончание"), fieldname: 'current_end', fieldtype: 'Date', precision: 1, read_only: 1, in_list_view: 1, columns: 1 },
                    { label: __("Предл. начало"), fieldname: 'proposed_start', fieldtype: 'Date', precision: 1, read_only: 1, in_list_view: 1, columns: 1 },
                    { label: __("Предл. окончание"), fieldname: 'proposed_end', fieldtype: 'Date', read_only: 1, in_list_view: 1, columns: 1 },
                    { label: __("Причины"), fieldname: 'reasons', fieldtype: 'Data', read_only: 1, in_list_view: 1, columns: 4 }
                ],
                data: preview_list
            }
        ],
        primary_action_label: __('Выполнить выбранные'),
        primary_action: function() {
            const seleted = this.fields_dict.dependencies_rows.grid.get_selected_children();
            if ( !seleted.length  ) {
                frappe.msgprint(__('Необходимо выбрать изменения'));
                return;
            }
            // Prepare changes payload
            let changes = seleted.map(function(p) {
                return {
                    task: p.task,
                    proposed_start: p.proposed_start,
                    proposed_end: p.proposed_end
                };
            });
            // If large, run async
            if (changes.length > LARGE_AMOUNT_THRESHOLD ) {
                frappe.confirm(
                    __('This operation affects {0} tasks and may take a long time. Run in background?', [changes.length]),
                    function() {
                        frappe.call({
                            method: "apply_propagation",
                            args: {changes: JSON.stringify(changes), mode: "async"},
                            callback: function(r) {
                                if (r && r.message && r.message.job_id) {
                                    frappe.show_alert(__('Propagation started in background (job {0})', [r.message.job_id]));
                                } else {
                                    frappe.show_alert(__('Propagation enqueued'));
                                }
                                d.hide();
                                frm.reload_doc();
                            }
                        });
                    },
                    function() {
                        // cancel
                    }
                );
                
            } else {
                // sync apply
                frappe.call({
                    method: "apply_propagation",
                    args: {changes: JSON.stringify(changes), mode: "sync"},
                    callback: function(r) {
                        if (r && r.message && r.message.success) {
                            frappe.show_alert(__('Выполнены изменения: {0}', [r.message.changed]));
                        } else {
                            frappe.msgprint(__('Error applying changes'));
                        }
                        d.hide();
                        frm.reload_doc();
                    }
                });
            }
        }, 
        secondary_action_label: __('Закрыть'),
        secondary_action: function() {
            d.hide();
        }
    });
    d.show();
}

//Issue - ISS-2024-02909
frappe.ui.form.on("Task", {
    refresh (frm) {
        // If this task is a virtual task linked to an Issue, redirect to that Issue
        if (frm.doc.type == "Issue" && frm.doc.custom_linked_issue) {
            //Очистить историю браузера
            history.replaceState(null, null, frappe.router.make_url( frappe.get_prev_route() ) );
            //Перенаправляем пользователя
            frappe.set_route("Form", "Issue", frm.doc.custom_linked_issue);
        }
    }
});

frappe.listview_settings['Task'] = {
    add_fields: ['custom_linked_issue'],
    get_form_link: function(doc) {
        if (doc.type == "Issue" && doc.custom_linked_issue) {
            return frappe.utils.get_form_link(
                "Issue",
                doc.custom_linked_issue
            );
        }
        return frappe.utils.get_form_link(
                "Task",
                doc.name
            );
    }
};
